const PAIRS = Object.entries(ES).sort((a, b) => b[0].length - a[0].length)

export const wantsEs = (req) => {
  const q = String(req.query?.lang || "")
  if (q) return q === "es"
  return /^es\b/i.test(String(req.headers?.["accept-language"] || ""))
}

export function toEs(html) {
  let s = String(html)
  for (const [en, es] of PAIRS) s = s.split(en).join(es)
  return s.replace(/<html lang="en"/, '<html lang="es"')
}
